import { Cart, CartItem, Category, ErrorEvent, Identity, PartyIdentification } from '../events';
/**
Description: Add a new line item to the cart. If the line item exists it will be replaced, including the quantity as an absolute value.
*/
export type AddToCart = {
    events: Array<Cart | CartItem | Identity | PartyIdentification | ErrorEvent>;
}

export class AddToCartBuilder {

    private addToCart: AddToCart = {
        events: []
    }

    private cart!: Cart;
    private cartItem!: CartItem;
    private errorEvent!: ErrorEvent;
    private identity!: Identity;
    private partyIdentification!: PartyIdentification;

    public withCart(cart: Cart) : AddToCartBuilder {
        this.cart = cart;
        return this;
    }
    public withCartItem(cartItem: CartItem) : AddToCartBuilder {
        this.cartItem = cartItem;
        return this;
    }
    public withErrorEvent(errorEvent: ErrorEvent) : AddToCartBuilder {
        this.errorEvent = errorEvent;
        return this;
    }
    public withIdentity(identity: Identity) : AddToCartBuilder {
        this.identity = identity;
        return this;
    }
    public withPartyIdentification(partyIdentification: PartyIdentification) : AddToCartBuilder {
        this.partyIdentification = partyIdentification;
        return this;
    }

    public build() : AddToCart {
        if(this.cart) {
            this.addToCart.events.push(this.cart);
        }
        if(this.cartItem) {
            this.addToCart.events.push(this.cartItem);
        }
        if(this.errorEvent) {
            this.addToCart.events.push(this.errorEvent);
        }
        if(this.identity) {
            this.addToCart.events.push(this.identity);
        }
        if(this.partyIdentification) {
            this.addToCart.events.push(this.partyIdentification);
        }

        return this.addToCart;
    }
}
